<?php $page_title='Pengajuan lokasi';$this->load->view('staff/_layout_start',compact('user','page_title')); ?>
<section class="staff-hero"><div><span class="staff-kicker">PETA TOKO</span><h1>Peninjauan lokasi</h1><p>Periksa titik dan pilihan publikasi pemilik sebelum menyetujui.</p></div></section>
<?php if ($this->input->get('tersimpan')): ?><div class="alert alert-success">Keputusan lokasi berhasil disimpan.</div><?php endif; ?>
<section class="staff-panel"><form method="get" class="staff-list-filter"><label>Cari<input class="form-control" type="search" name="q" maxlength="80" value="<?= html_escape($search) ?>" placeholder="Toko atau pengaju"></label><label>Status<select class="form-select" name="status"><?php foreach(array('pending'=>'Menunggu','approved'=>'Disetujui','rejected'=>'Ditolak') as $value=>$label): ?><option value="<?= $value ?>" <?= $status===$value?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></label><?php $this->load->view('staff/_list_size',array('per_page'=>$per_page)); ?><button type="submit">Terapkan</button></form><p class="staff-list-count"><?= number_format($total,0,',','.') ?> pengajuan</p><?php if (!$rows): ?><p>Belum ada pengajuan pada status ini.</p><?php endif; ?>
<?php foreach($rows as $row): ?><article class="staff-panel"><h3><?= html_escape($row['store_name']) ?></h3><p>Pengaju: <?= html_escape($row['applicant_name']) ?> · <?= html_escape($row['created_at']) ?></p><p>Koordinat: <?= html_escape($row['latitude'].', '.$row['longitude']) ?> · Pilihan: <?= html_escape(array('point'=>'Titik persis','area'=>'Area kecamatan','hidden'=>'Internal saja')[$row['display_mode']]??$row['display_mode']) ?></p><p><?= nl2br(html_escape($row['source_note'])) ?></p><p><a href="<?= site_url('pengelola/lokasi/'.$row['store_id']) ?>">Periksa lokasi toko</a> · <a href="<?= 'https://www.openstreetmap.org/?mlat='.rawurlencode($row['latitude']).'&mlon='.rawurlencode($row['longitude']).'#map=17/'.rawurlencode($row['latitude']).'/'.rawurlencode($row['longitude']) ?>" target="_blank" rel="noopener">Lihat titik pada peta ↗</a></p><?php if ($row['decision_note']): ?><p>Keputusan: <?= html_escape($row['decision_note']) ?></p><?php endif; ?><?php if ($row['status']==='pending'): ?><form method="post" action="<?= site_url('pengelola/pengajuan-lokasi/'.$row['id'].'/putusan') ?>"><input type="hidden" name="<?= $this->security->get_csrf_token_name() ?>" value="<?= $this->security->get_csrf_hash() ?>"><label class="form-label">Dasar keputusan<textarea class="form-control" name="decision_note" minlength="20" maxlength="500" rows="2" required></textarea></label><label class="form-check"><input class="form-check-input" type="checkbox" name="location_checked" value="1"><span class="form-check-label">Saya telah memeriksa koordinat dan pilihan publikasi.</span></label><button class="btn btn-primary" type="submit" name="decision" value="approved">Setujui</button> <button class="btn btn-outline-danger" type="submit" name="decision" value="rejected">Tolak</button></form><?php endif; ?></article><?php endforeach; ?>
<?php $this->load->view('staff/_pagination',array('base'=>site_url('pengelola/pengajuan-lokasi'),'params'=>array('q'=>$search,'status'=>$status,'per_page'=>$per_page),'page'=>$page,'pages'=>$pages)); ?></section>
<?php $this->load->view('staff/_layout_end'); ?>
